#include <iostream>
#include <string>
using namespace std;

const int d = 256;  // number of characters in alphabet
const int q = 101;  // a prime number for modular hashing

void rabinKarp(string text, string pattern) {
    int n = text.length();
    int m = pattern.length();
    int h = 1;  // d^(m-1) % q
    int p = 0;  // hash for pattern
    int t = 0;  // hash for text window

    // Compute h = d^(m-1) % q
    for (int i = 0; i < m - 1; i++)
        h = (h * d) % q;

    // Compute initial hash values
    for (int i = 0; i < m; i++) {
        p = (d * p + pattern[i]) % q;
        t = (d * t + text[i]) % q;
    }

    // Slide pattern over text
    for (int i = 0; i <= n - m; i++) {
        if (p == t) {
            // Hash match - verify character by character
            bool match = true;
            for (int j = 0; j < m; j++) {
                if (text[i + j] != pattern[j]) {
                    match = false;
                    break;
                }
            }
            if (match)
                cout << "Pattern found at index " << i << endl;
        }

        // Compute rolling hash for next window
        if (i < n - m) {
            t = (d * (t - text[i] * h) + text[i + m]) % q;
            if (t < 0) t += q;
        }
    }
}

int main() {
    string text = "GEEKS FOR GEEKS";
    string pattern = "GEEK";
    rabinKarp(text, pattern);
    // Output: Pattern found at index 0
    //         Pattern found at index 10
    return 0;
}

