vector<int> buildZArray(string s) {
    int n = s.length();
    vector<int> z(n, 0);
    int l = 0, r = 0;

    for (int i = 1; i < n; i++) {
        if (i < r) {
            z[i] = min(r - i, z[i - l]);
        }
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) {
            z[i]++;
        }
        if (i + z[i] > r) {
            l = i;
            r = i + z[i];
        }
    }
    return z;
}

void zSearch(string text, string pattern) {
    string concat = pattern + "$" + text;
    int m = pattern.length();
    vector<int> z = buildZArray(concat);

    for (int i = 0; i < (int)concat.length(); i++) {
        if (z[i] == m) {
            cout << "Pattern found at index " << i - m - 1 << endl;
        }
    }
}

