#include <stdio.h>
#include <string.h>

void buildZArray(char s[], int z[], int n) {
    int l = 0, r = 0;
    z[0] = 0;

    for (int i = 1; i < n; i++) {
        z[i] = 0;
        if (i < r) z[i] = (r - i < z[i - l]) ? r - i : z[i - l];
        while (i + z[i] < n && s[z[i]] == s[i + z[i]]) z[i]++;
        if (i + z[i] > r) { l = i; r = i + z[i]; }
    }
}

void zSearch(char text[], char pattern[]) {
    int m = strlen(pattern), n = strlen(text);
    int len = m + 1 + n;
    char concat[len + 1];
    sprintf(concat, "%s$%s", pattern, text);

    int z[len];
    buildZArray(concat, z, len);

    for (int i = 0; i < len; i++) {
        if (z[i] == m)
            printf("Pattern found at index %d\n", i - m - 1);
    }
}

int main() {
    zSearch("GEEKS FOR GEEKS", "GEEK");
